import json
facts = [
  {
    "id": "sample-coverage",
    "claim": "The data has 40 men's and 40 women's rows, with 20 brands and exactly 2 rows per brand in each gender group after trimming and case-normalizing brand labels.",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "measurements.assign(brand=measurements.brand.str.strip().str.lower()).groupby('menWomen').apply(lambda g: pd.Series({'jeans': len(g), 'brands': g.brand.nunique(), 'min_rows_per_brand': g.groupby('brand').size().min(), 'max_rows_per_brand': g.groupby('brand').size().max()}), include_groups=False)"
  },
  {
    "id": "front-dimensions",
    "claim": "Men's front pockets average 20.605 cm deep and 14.866 cm wide versus 13.778 cm and 13.721 cm for women, gaps of 6.827 cm (49.555%) and 1.145 cm (8.345%).",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "measurements.assign(frontDepth=measurements[['maxHeightFront','minHeightFront']].mean(axis=1), frontWidth=measurements[['maxWidthFront','minWidthFront']].mean(axis=1)).groupby('menWomen')[['frontDepth','frontWidth']].mean().T.assign(gap_cm=lambda t: t.men-t.women, men_vs_women_pct=lambda t: (t.men/t.women-1)*100).round(3)"
  },
  {
    "id": "back-dimensions",
    "claim": "The men's-versus-women's back-pocket gaps are much smaller: 0.886 cm (6.398%) for average depth and 0.393 cm (3.130%) for average width.",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "measurements.assign(backDepth=measurements[['maxHeightBack','minHeightBack']].mean(axis=1), backWidth=measurements[['maxWidthBack','minWidthBack']].mean(axis=1)).groupby('menWomen')[['backDepth','backWidth']].mean().T.assign(gap_cm=lambda t: t.men-t.women, men_vs_women_pct=lambda t: (t.men/t.women-1)*100).round(3)"
  },
  {
    "id": "front-back-within-gender",
    "claim": "Men's front pockets average 5.866 cm deeper than their back pockets (20.605 versus 14.739 cm), while women's front pockets average 0.075 cm shallower than their back pockets (13.778 versus 13.853 cm).",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "measurements.assign(frontDepth=measurements[['maxHeightFront','minHeightFront']].mean(axis=1), backDepth=measurements[['maxHeightBack','minHeightBack']].mean(axis=1)).groupby('menWomen')[['frontDepth','backDepth']].mean().assign(front_minus_back=lambda t: t.frontDepth-t.backDepth).round(3)"
  },
  {
    "id": "phone-height-clearance",
    "claim": "For a 14.4 cm height benchmark, 40 of 40 men's and 18 of 40 women's pockets clear it at the tallest point, while 37 of 40 men's and 9 of 40 women's clear it at the shortest point; the smallest minimum front width is 11.0 cm in both groups.",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "measurements.assign(tallest_clear=measurements.maxHeightFront.ge(14.4), shortest_clear=measurements.minHeightFront.ge(14.4)).groupby('menWomen').agg(**{'jeans': ('name','size'), 'maxHeightFront >= 14.4 cm': ('tallest_clear','sum'), 'minHeightFront >= 14.4 cm': ('shortest_clear','sum'), 'smallest minWidthFront (cm)': ('minWidthFront','min')})"
  },
  {
    "id": "brand-depth-gaps",
    "claim": "Men's average front depth exceeds women's for every brand shown; the gap ranges from 1.500 cm at Abercrombie to 10.250 cm at Ralph Lauren.",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "measurements.assign(brand=measurements.brand.str.strip().str.title().str.replace(\"Levi'S\", \"Levi's\"), frontDepth=measurements[['maxHeightFront','minHeightFront']].mean(axis=1)).groupby(['brand','menWomen']).frontDepth.mean().unstack().assign(gap_cm=lambda t: t.men-t.women).sort_values('gap_cm')[['women','men','gap_cm']].round(3)"
  },
  {
    "id": "price-depth-relationship",
    "claim": "Mean listed prices are 81.184 for men and 80.316 for women, while the within-group Spearman correlations of price with front depth are -0.269 for men and -0.196 for women.",
    "tables": {"measurements": "data/measurements.csv"},
    "code": "measurements.assign(frontDepth=measurements[['maxHeightFront','minHeightFront']].mean(axis=1)).groupby('menWomen').apply(lambda g: pd.Series({'jeans': len(g), 'mean_price': g.price.mean(), 'mean_front_depth_cm': g.frontDepth.mean(), 'price_depth_spearman': g.price.corr(g.frontDepth, method='spearman')}), include_groups=False).round(3)"
  }
]
with open('facts.json','w') as f: json.dump(facts,f,indent=2,ensure_ascii=False)
PY
python /tmp/make_facts.py
cat > /tmp/verify_facts.py <<'PY'
import json, pandas as pd, numpy as np
with open('facts.json') as f: facts=json.load(f)
for i, fact in enumerate(facts,1):
    scope={'pd':pd,'np':np}
    for name,path in fact['tables'].items(): scope[name]=pd.read_csv(path)
    print('\n'+'='*100)
    print(f"{i}. {fact['id']}\nCLAIM: {fact['claim']}\nCODE: {fact['code']}\nOUTPUT:")
    print(eval(fact['code'],scope))
PY
